/** A fresh fixture per frame/run. No shared mutable product or session state. */
export function researchCase(id) {
  const oracle = caseOracles.find(item=>item.id===id);
  if (!oracle) throw new Error('UNKNOWN_PRICE_RESEARCH_CASE');
  const request = structuredClone(base);
  if (id==='PC-02') request.rules.costComponents.shipping={amount:'3000',ruleId:'RESEARCH_EXPLICIT_3000_SHIPPING'};
  if (id==='PC-03') request.rules.costComponents.shipping=null;
  if (id==='PC-04') request.input.comparisonTotal=null;
  if (id==='PC-09') request.priceBook.offers[0].effectiveTo=fixtureTime;
  if (id==='PC-10') { request.input.lines[0].quantity='9';request.priceBook.offers[0].minQuantity='10'; }
  if (id==='PC-11') request.input.lines[0].unit='pack';
  if (id==='PC-15') request.rules.rounding=null;
  return {origin:researchOrigin,...structuredClone(oracle),request,periodInput:{perDelivery:'10',weeklyVisits:'1',period:null}};
}
